SELECT 
FROM crm_customer
WHERE tenant_id = #{tenantId}
  AND active_name_key = #{activeNameKey}
  AND operating_status != '已归档'
  AND del_flag = '0'

SELECT 
FROM crm_customer
WHERE tenant_id = #{tenantId}
  AND primary_owner_id = #{primaryOwnerId}
  AND del_flag = '0'
ORDER BY create_time DESC

SELECT 
FROM crm_customer
WHERE tenant_id = #{tenantId}
  AND owner_dept_id = #{ownerDeptId}
  AND del_flag = '0'
ORDER BY create_time DESC

SELECT 
FROM crm_customer
WHERE tenant_id = #{tenantId} AND del_flag = '0'

    AND name LIKE CONCAT('%', #{query.name}, '%')


    AND operating_status = #{query.operatingStatus}


    AND lifecycle_stage = #{query.lifecycleStage}


    AND primary_owner_id = #{query.primaryOwnerId}


    AND owner_dept_id = #{query.ownerDeptId}


    AND importance = #{query.importance}


    AND source = #{query.source}


    AND industry = #{query.industry}

ORDER BY create_time DESC

SELECT c.*, COALESCE(fu.follow_up_record_count, 0) AS follow_up_record_count, co.collaborator_names, tl.latest_activity_at, fu.latest_visit_at, oh.latest_assignment_at FROM crm_customer c LEFT JOIN ( SELECT tenant_id, customer_id, COUNT(*) AS follow_up_record_count, MAX(CASE WHEN method IN ('IN_PERSON', '面谈', '拜访') THEN follow_up_at END) AS latest_visit_at FROM crm_follow_up WHERE tenant_id = #{tenantId} AND del_flag = '0' AND is_voided = 0 GROUP BY tenant_id, customer_id ) fu ON fu.tenant_id = c.tenant_id AND fu.customer_id = c.customer_id LEFT JOIN ( SELECT tenant_id, customer_id, GROUP_CONCAT(user_name ORDER BY create_time SEPARATOR '、') AS collaborator_names FROM crm_customer_owner WHERE tenant_id = #{tenantId} AND role_type = 'COLLABORATOR' AND status = 'ACTIVE' GROUP BY tenant_id, customer_id ) co ON co.tenant_id = c.tenant_id AND co.customer_id = c.customer_id LEFT JOIN ( SELECT tenant_id, customer_id, MAX(create_time) AS latest_activity_at FROM crm_customer_timeline WHERE tenant_id = #{tenantId} GROUP BY tenant_id, customer_id ) tl ON tl.tenant_id = c.tenant_id AND tl.customer_id = c.customer_id LEFT JOIN ( SELECT tenant_id, customer_id, MAX(create_time) AS latest_assignment_at FROM crm_owner_change WHERE tenant_id = #{tenantId} GROUP BY tenant_id, customer_id ) oh ON oh.tenant_id = c.tenant_id AND oh.customer_id = c.customer_id WHERE c.tenant_id = #{tenantId} AND c.del_flag = '0'
AND EXISTS ( SELECT 1 FROM sys_dept d WHERE d.dept_id = c.owner_dept_id AND d.status = '0' AND d.del_flag = '0' AND (d.dept_id = #{operatorDeptId} OR FIND_IN_SET(#{operatorDeptId}, d.ancestors)) )
AND (c.primary_owner_id = #{operatorId} OR FIND_IN_SET(#{operatorId}, REPLACE(COALESCE(c.collaborator_ids, ''), ' ', '')))
AND c.name LIKE CONCAT('%', #{customer.name}, '%')
AND c.operating_status = #{customer.operatingStatus}
AND c.lifecycle_stage = #{customer.lifecycleStage}
AND c.importance = #{customer.importance}
AND c.source = #{customer.source}
AND c.industry = #{customer.industry}
ORDER BY c.create_time DESC

mapper.update:
UPDATE crm_customer
SET follow_up_status = #{followUpStatus},
    follow_up_status_calculated_at = NOW(),
    update_by = #{updateBy},
    update_time = NOW(),
    version = version + 1
WHERE tenant_id = #{tenantId}
  AND customer_id = #{customerId}
  AND version = #{version}
  AND del_flag = '0'

